//! Claude Code managed settings for an enrolled device.
//!
//! The managed file is machine-wide and root-owned, so a user can't edit
//! it. It points Claude Code at Smartflow, presents the device cert from
//! enrollment, pulls the vkey from the keystore through `apiKeyHelper`,
//! and runs Shield as a hook that user or project settings can't remove.
//!
//! `env` values are not shell-expanded, so the cert paths are absolute
//! and the file has to be generated by the user who enrolled.

use std::path::{Path, PathBuf};

use serde_json::{json, Value};

use super::device_identity::{self, CERT_FILE, KEY_FILE};
use super::state::OrgState;

/// How long Claude Code caches the helper's output, so a rotated vkey is
/// picked up without a restart.
const API_KEY_HELPER_TTL_MS: &str = "900000";

/// Where Claude Code reads managed settings on this OS.
pub fn default_path() -> PathBuf {
    #[cfg(target_os = "macos")]
    {
        PathBuf::from("/Library/Application Support/ClaudeCode/managed-settings.json")
    }
    #[cfg(windows)]
    {
        PathBuf::from(r"C:\Program Files\ClaudeCode\managed-settings.json")
    }
    #[cfg(not(any(target_os = "macos", windows)))]
    {
        PathBuf::from("/etc/claude-code/managed-settings.json")
    }
}

fn quoted(bin: &Path) -> String {
    let s = bin.to_string_lossy().replace('\\', "/");
    format!("\"{}\"", s.replace('"', "\\\""))
}

/// Exit 2 is the only status Claude Code treats as a block, so a missing
/// or crashing binary is turned into one.
fn hook(bin: &Path, flag: &str) -> Value {
    json!({
        "type": "command",
        "command": format!("{} {flag} --hook-dialect claude || exit 2", quoted(bin)),
    })
}

pub fn render(state: &OrgState, bin: &Path, cert: &Path, key: &Path, extra_ca: Option<&Path>) -> Value {
    let mut env = json!({
        "ANTHROPIC_BASE_URL": state.smartflow_url.trim_end_matches('/'),
        "CLAUDE_CODE_CLIENT_CERT": cert.to_string_lossy(),
        "CLAUDE_CODE_CLIENT_KEY": key.to_string_lossy(),
        "CLAUDE_CODE_API_KEY_HELPER_TTL_MS": API_KEY_HELPER_TTL_MS,
    });
    if let Some(ca) = extra_ca {
        env["NODE_EXTRA_CA_CERTS"] = json!(ca.to_string_lossy());
    }
    json!({
        "apiKeyHelper": format!("{} --api-key", quoted(bin)),
        "env": env,
        "hooks": {
            "PreToolUse": [{"matcher": "*", "hooks": [hook(bin, "--check-hook")]}],
            "PostToolUse": [{"matcher": "*", "hooks": [hook(bin, "--check-hook-post")]}],
        },
        "allowManagedHooksOnly": true,
        "permissions": {"disableBypassPermissionsMode": "disable"},
    })
}

/// Build the settings for this enrollment. Fails if the device has no
/// client cert, since Claude Code can't reach an mTLS listener without one.
pub fn for_enrolled(state: &OrgState, extra_ca: Option<&Path>) -> anyhow::Result<Value> {
    let cert = device_identity::path(CERT_FILE)?;
    let key = device_identity::path(KEY_FILE)?;
    if !cert.is_file() || !key.is_file() {
        anyhow::bail!(
            "no device certificate at {}. Re-enroll against a Smartflow with a device CA configured.",
            cert.display()
        );
    }
    let bin = std::env::current_exe()?;
    let bin = bin.canonicalize().unwrap_or(bin);
    Ok(render(state, &bin, &cert, &key, extra_ca))
}

/// Cursor's MDM hooks file. User and project hooks can't cancel a deny
/// from it.
pub fn cursor_default_path() -> PathBuf {
    #[cfg(target_os = "macos")]
    {
        PathBuf::from("/Library/Application Support/Cursor/hooks.json")
    }
    #[cfg(windows)]
    {
        PathBuf::from(r"C:\ProgramData\Cursor\hooks.json")
    }
    #[cfg(not(any(target_os = "macos", windows)))]
    {
        PathBuf::from("/etc/cursor/hooks.json")
    }
}

/// Cursor system hooks running Shield. Permission events fail closed;
/// post events can't deny, so a missing binary doesn't wedge the IDE.
pub fn render_cursor(bin: &Path) -> Value {
    let pre = format!("{} --check-hook --hook-dialect cursor", quoted(bin));
    let post = format!("{} --check-hook-post --hook-dialect cursor", quoted(bin));
    let mut hooks = serde_json::Map::new();
    for ev in ["preToolUse", "beforeShellExecution", "beforeMCPExecution", "beforeReadFile"] {
        hooks.insert(ev.into(), json!([{"command": pre, "failClosed": true}]));
    }
    for ev in ["afterShellExecution", "afterMCPExecution", "postToolUse"] {
        hooks.insert(ev.into(), json!([{"command": post, "failClosed": false}]));
    }
    json!({"version": 1, "hooks": hooks})
}

pub fn cursor_for_enrolled() -> anyhow::Result<Value> {
    let bin = std::env::current_exe()?;
    let bin = bin.canonicalize().unwrap_or(bin);
    Ok(render_cursor(&bin))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn state() -> OrgState {
        OrgState {
            smartflow_url: "https://sf.example/".into(),
            vkey: String::new(),
            device_id: "d".into(),
            policy_group: "g".into(),
            owner_email: None,
            enrolled_at: String::new(),
            platform: "macos".into(),
            device_name: "n".into(),
            device_fingerprint: "f".into(),
            bundle_pubkey: None,
        }
    }

    #[test]
    fn renders_gateway_cert_helper_and_locked_hooks() {
        let bin = Path::new("/Applications/Aperion Shield/aperion-shield");
        let v = render(&state(), bin, Path::new("/h/device.crt"), Path::new("/h/device.key"), None);
        assert_eq!(v["env"]["ANTHROPIC_BASE_URL"], "https://sf.example");
        assert_eq!(v["env"]["CLAUDE_CODE_CLIENT_CERT"], "/h/device.crt");
        assert_eq!(v["env"]["CLAUDE_CODE_CLIENT_KEY"], "/h/device.key");
        assert!(v["env"].get("NODE_EXTRA_CA_CERTS").is_none());
        assert_eq!(v["apiKeyHelper"], "\"/Applications/Aperion Shield/aperion-shield\" --api-key");
        let pre = v["hooks"]["PreToolUse"][0]["hooks"][0]["command"].as_str().unwrap();
        assert!(pre.ends_with("--check-hook --hook-dialect claude || exit 2"));
        let post = v["hooks"]["PostToolUse"][0]["hooks"][0]["command"].as_str().unwrap();
        assert!(post.contains("--check-hook-post"));
        assert_eq!(v["allowManagedHooksOnly"], true);
        assert_eq!(v["permissions"]["disableBypassPermissionsMode"], "disable");
        assert!(!v.to_string().contains("sk-sf-"));
    }

    #[test]
    fn cursor_hooks_fail_closed_on_permission_events() {
        let v = render_cursor(Path::new("/usr/local/bin/aperion-shield"));
        assert_eq!(v["version"], 1);
        for ev in ["preToolUse", "beforeShellExecution", "beforeMCPExecution", "beforeReadFile"] {
            assert_eq!(v["hooks"][ev][0]["failClosed"], true, "{ev}");
            assert!(v["hooks"][ev][0]["command"].as_str().unwrap().contains("--check-hook --hook-dialect cursor"));
        }
        assert_eq!(v["hooks"]["postToolUse"][0]["failClosed"], false);
    }

    #[test]
    fn extra_ca_is_optional() {
        let v = render(
            &state(),
            Path::new("/b"),
            Path::new("/c"),
            Path::new("/k"),
            Some(Path::new("/corp-ca.pem")),
        );
        assert_eq!(v["env"]["NODE_EXTRA_CA_CERTS"], "/corp-ca.pem");
    }
}
